-- CentreMate: no student data is readable anonymously; directory access is an RPC projection.
create table public.admins(email text primary key check(email=lower(email)));
create table public.allowed_domains(domain text primary key check(domain=lower(domain)));
create table public.email_exceptions(email text primary key check(email=lower(email)));
create table public.exams(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 120),exam_date date not null,active boolean not null default true);
create table public.centres(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 160),address text not null check(length(address) between 1 and 500),unique(name,address));
create table public.registrations(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams on delete cascade,centre_id uuid not null references public.centres on delete cascade,email text not null check(email=lower(email)),name text not null check(length(name) between 1 and 80),hostel text not null check(hostel in ('Uni 1','Uni 2')),departure time,whatsapp text check(whatsapp is null or whatsapp ~ '^[1-9][0-9]{7,14}$'),visible boolean not null default false,going boolean not null default false,ready_until timestamptz,source text not null default 'website' check(source in ('website','form')),unique(exam_id,email));
create table public.centre_requests(id uuid primary key default gen_random_uuid(),email text not null,name text not null check(length(name) between 1 and 160),address text not null check(length(address) between 1 and 500),created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admins where email=lower(auth.jwt()->>'email')) and coalesce((auth.jwt()->>'email_verified')::boolean, (select email_confirmed_at is not null from auth.users where id=auth.uid()),false) $$;
create function public.is_approved() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null) and (public.is_admin() or exists(select 1 from public.allowed_domains where domain=split_part(lower(auth.jwt()->>'email'),'@',2)) or exists(select 1 from public.email_exceptions where email=lower(auth.jwt()->>'email'))) $$;
-- Closed by default: admins configure exact verified Scaler domains and exceptions.
do $$ declare t text; begin foreach t in array array['admins','allowed_domains','email_exceptions','exams','centres','registrations','centre_requests'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy admin_all on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',t); end loop; end $$;
create policy read_exams on public.exams for select to anon,authenticated using(true);
create policy read_centres on public.centres for select to anon,authenticated using(true);
create policy own_read on public.registrations for select to authenticated using(public.is_approved() and email=lower(auth.jwt()->>'email'));
create policy own_insert on public.registrations for insert to authenticated with check(public.is_approved() and email=lower(auth.jwt()->>'email') and source='website' and (ready_until is null or ready_until <= now()+interval '2 hours'));
create policy own_update on public.registrations for update to authenticated using(public.is_approved() and email=lower(auth.jwt()->>'email')) with check(public.is_approved() and email=lower(auth.jwt()->>'email') and source='website' and (ready_until is null or ready_until <= now()+interval '2 hours'));
create policy own_delete on public.registrations for delete to authenticated using(public.is_approved() and email=lower(auth.jwt()->>'email'));
create policy request_insert on public.centre_requests for insert to authenticated with check(public.is_approved() and email=lower(auth.jwt()->>'email'));
create function public.directory(p_exam uuid,p_centre uuid) returns table(id uuid,name text,hostel text,departure time,going boolean,ready_until timestamptz,has_contact boolean) language sql stable security definer set search_path='' as $$ select r.id,r.name,r.hostel,r.departure,r.going,case when r.ready_until>now() then r.ready_until else null end,r.whatsapp is not null from public.registrations r where public.is_approved() and r.visible and r.exam_id=p_exam and r.centre_id=p_centre $$;
create function public.centre_counts(p_exam uuid) returns table(centre_id uuid,total bigint) language sql stable security definer set search_path='' as $$ select r.centre_id,count(*) from public.registrations r where public.is_approved() and r.visible and r.exam_id=p_exam group by r.centre_id $$;
create function public.contact(p_registration uuid) returns text language sql stable security definer set search_path='' as $$ select r.whatsapp from public.registrations r where public.is_approved() and r.visible and r.id=p_registration and exists(select 1 from public.registrations me where me.email=lower(auth.jwt()->>'email') and me.exam_id=r.exam_id and me.centre_id=r.centre_id) $$;
-- Imports never overwrite a student's choices or publish personal information.
create function public.import_form(rows jsonb) returns integer language plpgsql security definer set search_path='' as $$ declare item jsonb; n integer:=0; begin if not public.is_admin() then raise exception 'Admin only' using errcode='42501'; end if; if jsonb_array_length(rows)>1000 then raise exception 'Maximum 1000 rows'; end if; for item in select * from jsonb_array_elements(rows) loop insert into public.registrations(exam_id,centre_id,email,name,hostel,source,visible) values((item->>'exam_id')::uuid,(item->>'centre_id')::uuid,lower(trim(item->>'email')),item->>'name',item->>'hostel','form',false) on conflict(exam_id,email) do nothing; n:=n+1; end loop; return n; end $$;
-- Sync uses a dedicated server identity, never a publicly callable service-role import.
revoke all on function public.import_form(jsonb) from public,anon;
grant execute on function public.import_form(jsonb) to authenticated;
create index registrations_directory on public.registrations(exam_id,centre_id) where visible;
-- Explicit API grants make this independent of project default privileges.
revoke all on public.admins,public.allowed_domains,public.email_exceptions,public.registrations,public.centre_requests from anon;
grant usage on schema public to anon,authenticated;
grant select on public.exams,public.centres to anon;
grant select,insert,update,delete on public.admins,public.allowed_domains,public.email_exceptions,public.exams,public.centres,public.registrations,public.centre_requests to authenticated;
